-- ══════════════════════════════════════════════════════════════════════════════
--  SEED — dados de teste genéricos
--
--  Como usar:
--    1. Arranca a API uma vez para criar o ficheiro e correr as migrações:
--         dotnet run --project src/BalanceProjectionApp.ApiService
--    2. Para a API (Ctrl+C)
--    3. Corre este script:
--         sqlite3 src/BalanceProjectionApp.ApiService/balance_projection.db < seed.sql
--
--  O que é criado:
--    • 1 Conta Operacional (saldo pré-calculado com base nas parcelas pagas)
--    • 2 Colaboradores (Ana Silva 10%, João Ferreira 15%)
--    • 3 Receitas com parcelas (arrendamento, venda com comissão, consultoria)
--    • 5 Despesas com parcelas (fixa, pontual, recorrente, financiamento)
--    • 1 Financiamento (Empréstimo Banco 30 000 €)
-- ══════════════════════════════════════════════════════════════════════════════

PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;

-- ── Conta ─────────────────────────────────────────────────────────────────────
-- Saldo = crédito financiamento 30 000
--       + receitas pagas       20 300  (arrendamento 4 800 + venda 13 500 + consultoria 2 000)
--       - despesas pagas       20 215  (renda 7 200 + salário 9 000 + seguro 650 + manutenção 365 + financiamento 3 000)
--       = 30 085.00

-- ── Colaboradores ─────────────────────────────────────────────────────────────

-- ── Receitas ──────────────────────────────────────────────────────────────────
-- Categoria (INTEGER): Vendas=0, Arrendamentos=1, Outros=2

-- ── Despesas ──────────────────────────────────────────────────────────────────
-- TipoDespesa (TEXT): 'Pontual' | 'Fixa' | 'Recorrente'
-- Periodicidade (TEXT): 'Mensal' | 'Trimestral' | 'Semestral' | 'Anual'
-- Categoria (INTEGER): Servicos=0, Produtos=1, Salarios=2, Impostos=3, IVA=4, Financiamento=5, Outro=6

-- ── Financiamento ─────────────────────────────────────────────────────────────
   'a1a1a1a1-0000-0000-0000-000000000001', 'd4d4d4d4-0000-0000-0000-000000000005',
   '2026-01-05 00:00:00', 0);

-- ── Parcelas — Arrendamento Escritório Porto (Jan–Jul, Jan–Jun pagas) ─────────

-- ── Parcelas — Venda Fração A (Ana Silva 10%: bruto 15 000, líquido 13 500) ───

-- ── Parcelas — Consultoria Empresa XYZ ────────────────────────────────────────

-- ── Parcelas — Renda Escritório (Jan–Jul, Jan–Jun pagas) ──────────────────────

-- ── Parcelas — Salário Administrativo (Jan–Jul, Jan–Mai pagas) ───────────────

-- ── Parcelas — Seguro Responsabilidade Civil (Mar, paga) ─────────────────────

-- ── Parcelas — Manutenção Equipamentos (Jan–Abr, Jan–Mar pagas) ──────────────

-- ── Parcelas — Empréstimo Banco prestação (Jan–Jul, Jan–Jun pagas) ────────────

COMMIT;
PRAGMA foreign_keys = ON;
